def legendre(a, p):
    if p == 2:
        return 1 if a % 2 == 1 else 0
    res = pow(a, (p - 1) // 2, p)
    return 1 if res == 1 else -1

p = 61
count_qnr = 0
for a in range(1, p):
    if legendre(a, p) == -1:
        count_qnr += 1

print(f"Number of QNRs modulo {p}: {count_qnr}")

def is_permutation_polynomial(a1, a3, p):
    """Checks if P(x) = a1*x + a3*x^3 is a permutation polynomial mod p."""
    values = set()
    for x in range(p):
        value = (a1 * x + a3 * x**3) % p
        values.add(value)
    return len(values) == p

p = 11
count = 0
for a1 in range(p):
    for a3 in range(p):
        if is_permutation_polynomial(a1, a3, p):
            count += 1
print(f"The number of pairs (a1, a3) that make P(x) a PP mod 11 is: {count}")

